"use client";

import { useEffect, useMemo, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { cn } from "@/lib/utils";

export type ReflowAlign = "left" | "center" | "right";

export interface ReflowProps {
  phrases?: string[];
  index?: number;
  columnWidth?: number;
  stiffness?: number;
  damping?: number;
  stagger?: number;
  enterScale?: number;
  wordGap?: number;
  lineHeight?: number;
  align?: ReflowAlign;
  auto?: boolean;
  interval?: number;
  traceMoves?: boolean;
  accentColor?: string;
  paused?: boolean;
  reducedMotion?: boolean;
  className?: string;
}

const STAGGER_CAP = 20;

interface WordProps {
  text: string;
  animateLayout: boolean;
  spring: { type: "spring"; stiffness: number; damping: number };
  delay: number;
  enterScale: number;
  wordGap: number;
  traceMoves: boolean;
  accentColor: string;
}

function Word({
  text,
  animateLayout,
  spring,
  delay,
  enterScale,
  wordGap,
  traceMoves,
  accentColor,
}: WordProps) {
  const [moving, setMoving] = useState(false);

  return (
    <motion.span
      layout={animateLayout ? "position" : false}
      onLayoutAnimationStart={() => traceMoves && setMoving(true)}
      onLayoutAnimationComplete={() => setMoving(false)}
      initial={{ opacity: 0, scale: enterScale }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: enterScale, transition: { duration: 0.15 } }}
      transition={
        animateLayout
          ? {
              layout: { ...spring, delay },
              opacity: { duration: 0.22 },
              scale: { duration: 0.26, ease: [0.22, 1, 0.36, 1] },
            }
          : { duration: 0 }
      }
      className="inline-block"
      style={{
        marginRight: `${wordGap}em`,
        color: moving && traceMoves ? accentColor : undefined,
        transition: traceMoves ? "color 260ms ease-out" : undefined,
      }}
    >
      {text}
    </motion.span>
  );
}

export default function Reflow({
  phrases = [],
  index,
  columnWidth = 100,
  stiffness = 340,
  damping = 34,
  stagger = 14,
  enterScale = 0.82,
  wordGap = 0.3,
  lineHeight = 1.6,
  align = "left",
  auto = true,
  interval = 3600,
  traceMoves = false,
  accentColor = "#a855f7",
  paused = false,
  reducedMotion = false,
  className,
}: ReflowProps) {
  const [self, setSelf] = useState(0);
  const controlled = index !== undefined;
  const current = controlled ? index : self;
  const halted = paused || reducedMotion;

  useEffect(() => {
    if (controlled || !auto || halted || phrases.length < 2) return;
    const id = setTimeout(
      () => setSelf((n) => (n + 1) % phrases.length),
      Math.max(200, interval),
    );
    return () => clearTimeout(id);
  }, [controlled, auto, halted, interval, phrases.length, current]);

  const text = phrases[current % Math.max(1, phrases.length)] ?? "";

  const words = useMemo(() => {
    const seen = new Map<string, number>();
    return text
      .split(/\s+/)
      .filter(Boolean)
      .map((word) => {
        const nth = (seen.get(word) ?? 0) + 1;
        seen.set(word, nth);
        return { key: `${word}#${nth}`, text: word };
      });
  }, [text]);

  const spring = {
    type: "spring" as const,
    stiffness,
    damping,
  };

  return (
    <div
      className={cn("w-full", className)}
      style={{
        textAlign: align,
        lineHeight,
      }}
    >
      <div
        className={cn(
          align === "center" ? "mx-auto" : align === "right" ? "ml-auto" : null,
        )}
        style={{ width: `${columnWidth}%` }}
      >
        <AnimatePresence mode="popLayout" initial={false}>
          {words.map((word, i) => (
            <Word
              key={word.key}
              text={word.text}
              animateLayout={!reducedMotion}
              spring={spring}
              delay={(Math.min(i, STAGGER_CAP) * stagger) / 1000}
              enterScale={enterScale}
              wordGap={wordGap}
              traceMoves={traceMoves}
              accentColor={accentColor}
            />
          ))}
        </AnimatePresence>
      </div>
    </div>
  );
}
